# backend/tests/test_trigger_setup_window.py
"""TRADING-REVIEW-PHASE-C T7 (review M4, decision D2): the stock trigger honours
`trigger.setup_window_bars`.

With W = setup_window_bars, a momentum event (MACD histogram cross, RSI floor /
ceiling cross, stochastic oversold / overbought cross) counts if it happened at
some bar k within the last W bars (k = -1 .. -W) AND its state still holds on the
last bar. W = 1 is the pre-T7 behaviour (event on the last bar only).
"""
import copy
import itertools

import pytest

from app.scoring.stock_scorer import _horizon_cfg, _rule_trigger
from tests.test_stock_scorer_events import _bars_up
from tests.test_stock_scorer_stock_mode import _bars, _bars_rvol, _trigger_bars_macd_cross


# ── Test 1: W = 1 reproduces today's results on the existing trigger fixtures ──

def _macd_cross_no_candle():
    bars = _trigger_bars_macd_cross()
    bars[-1]["close"] = bars[-1]["open"] - 0.5
    bars[-1]["low"] = bars[-1]["close"] - 0.3
    return bars


def _macd_cross_candle():
    bars = _trigger_bars_macd_cross()
    bars[-1]["close"] = bars[-1]["open"] + 1.0
    bars[-1]["high"] = bars[-1]["close"] + 0.3
    return bars


# Bar fixtures used by the existing trigger tests in tests/test_stock_scorer*.py.
_FIXTURES = {
    "macd_cross": _trigger_bars_macd_cross,
    "macd_cross_no_candle": _macd_cross_no_candle,
    "macd_cross_candle": _macd_cross_candle,
    "bars_up": lambda: _bars(120, "up"),
    "bars_down": lambda: _bars(120, "down"),
    "bars_flat": lambda: _bars(120, "flat"),
    "bars_rvol": lambda: _bars_rvol(n=30, current_vol_mult=2.5),
    "bars_up_events": _bars_up,
}


def _random_walk(seed, n=120):
    """Seeded random-walk bars. The fixtures above rarely fire a bullish event, so
    these add bars where MACD / RSI / stochastic crosses land on varied bars."""
    import random

    rng = random.Random(seed)
    bars, price = [], 100.0
    for _ in range(n):
        o = price
        price = max(1.0, price + rng.gauss(0.0, 1.5))
        hi = max(o, price) + abs(rng.gauss(0.0, 0.6))
        lo = min(o, price) - abs(rng.gauss(0.0, 0.6))
        bars.append({"open": o, "high": hi, "low": lo, "close": price,
                     "volume": int(1_000_000 * (0.5 + rng.random()))})
    return bars


for _seed in range(12):
    _FIXTURES[f"walk_{_seed:02d}"] = (lambda s=_seed: _random_walk(s))

# cfg variants the existing trigger tests apply on top of the horizon config.
_CFG_VARIANTS = {
    "default": {},
    "required_0": {"momentum_signals_for_pass": 0},
    "rising_off": {"macd_histogram_rising": False},
    "vol_lookback_5": {"volume_lookback_bars": 5},
}

W1_CASES = list(itertools.product(
    sorted(_FIXTURES),
    ("Intraday", "Swing", "Position"),
    ("Bullish", "Bearish"),
    ("stock", "options"),
    sorted(_CFG_VARIANTS),
))


def _run_case(case):
    fixture, horizon, direction, mode, variant = case
    cfg = copy.deepcopy(_horizon_cfg(horizon))
    cfg["trigger"].update(_CFG_VARIANTS[variant])
    cfg["trigger"]["setup_window_bars"] = 1
    bars = _FIXTURES[fixture]()
    volumes = [b["volume"] for b in bars]
    result, vol_bonus = _rule_trigger(bars, cfg, volumes, direction, scoring_mode=mode)
    d = result.detail
    return (result.status, result.score, d["candle"], d["macd_pass"], d["rsi_pass"],
            d["stoch_pass"], d["momentum_count"], d["volume_bonus"], vol_bonus)


