# ── Synthetic indicator series for the window shapes ───────────────────────────

def _flat_bars(n=60):
    # Flat closes: no candle pattern and no RSI divergence (price lows / highs
    # never make a new extreme), so only the mocked crosses drive the flags.
    return _bars(n, "flat")


def _detail(monkeypatch, direction, W, *, hist=None, rsi=None, stoch=None, horizon="Swing"):
    import app.scoring.stock_scorer as ss

    if hist is not None:
        monkeypatch.setattr(ss, "_macd_histogram", lambda *a, **k: list(hist))
    if rsi is not None:
        monkeypatch.setattr(ss, "_rsi", lambda *a, **k: list(rsi))
    if stoch is not None:
        monkeypatch.setattr(ss, "_stoch", lambda *a, **k: (list(stoch[0]), list(stoch[1])))
    cfg = copy.deepcopy(_horizon_cfg(horizon))
    if W is None:
        cfg["trigger"].pop("setup_window_bars", None)
    else:
        cfg["trigger"]["setup_window_bars"] = W
    bars = _flat_bars()
    volumes = [b["volume"] for b in bars]
    result, _ = _rule_trigger(bars, cfg, volumes, direction, scoring_mode="stock")
    return result.detail


# Indices: the last bar is index -1 ("0 bars ago"); "4 bars ago" is index -5,
# "9 bars ago" is index -10. The window W covers indices -1 .. -W.

# MACD histogram — bullish
HIST_UP_4_AGO_HOLDS = [-1.0] * 20 + [0.5, 0.6, 0.7, 0.8, 0.9]
HIST_UP_4_AGO_LOST = [-1.0] * 20 + [0.5, 0.6, 0.2, -0.1, -0.2]
HIST_UP_9_AGO_HOLDS = [-1.0] * 20 + [0.5] + [0.6] * 9
# MACD histogram — bearish mirror
HIST_DOWN_4_AGO_HOLDS = [1.0] * 20 + [-0.5, -0.6, -0.7, -0.8, -0.9]
HIST_DOWN_4_AGO_LOST = [1.0] * 20 + [-0.5, -0.6, -0.2, 0.1, 0.2]

# RSI (Swing floor 38, ceiling 60)
RSI_UP_4_AGO_HOLDS = [30.0] * 30 + [40.0, 42.0, 44.0, 45.0, 46.0]
RSI_UP_4_AGO_LOST = [30.0] * 30 + [40.0, 42.0, 37.0, 36.0, 35.0]
RSI_UP_9_AGO_HOLDS = [30.0] * 30 + [40.0] * 10
RSI_DOWN_4_AGO_HOLDS = [70.0] * 30 + [58.0, 56.0, 54.0, 52.0, 50.0]
RSI_DOWN_4_AGO_LOST = [70.0] * 30 + [58.0, 56.0, 61.0, 62.0, 63.0]

# Stochastic (K, D). Swing oversold threshold 30 * 1.05 = 31.5; overbought 70 * 0.95 = 66.5.
STOCH_UP_4_AGO_HOLDS = ([20.0] * 20 + [40.0, 45.0, 50.0, 55.0, 60.0],
                        [25.0] * 20 + [30.0, 35.0, 40.0, 45.0, 50.0])
STOCH_UP_4_AGO_LOST = ([20.0] * 20 + [40.0, 45.0, 50.0, 55.0, 40.0],
                       [25.0] * 20 + [30.0, 35.0, 40.0, 45.0, 50.0])
STOCH_UP_9_AGO_HOLDS = ([20.0] * 20 + [40.0] + [50.0] * 9,
                        [25.0] * 20 + [30.0] + [40.0] * 9)
STOCH_DOWN_4_AGO_HOLDS = ([80.0] * 20 + [60.0, 55.0, 50.0, 45.0, 40.0],
                          [75.0] * 20 + [70.0, 65.0, 60.0, 55.0, 50.0])
STOCH_DOWN_4_AGO_LOST = ([80.0] * 20 + [60.0, 55.0, 50.0, 45.0, 60.0],
                         [75.0] * 20 + [70.0, 65.0, 60.0, 55.0, 50.0])


# ── Test 2: a cross 4 bars ago whose state still holds counts with W=8, not W=1 ─

def test_macd_cross_up_4_bars_ago_counts_within_window(monkeypatch):
    assert _detail(monkeypatch, "Bullish", 8, hist=HIST_UP_4_AGO_HOLDS)["macd_pass"] is True
    assert _detail(monkeypatch, "Bullish", 1, hist=HIST_UP_4_AGO_HOLDS)["macd_pass"] is False


def test_window_boundary_is_last_w_bars_including_the_last_bar(monkeypatch):
    # Event at index -5: inside the last 5 bars, outside the last 4.
    assert _detail(monkeypatch, "Bullish", 5, hist=HIST_UP_4_AGO_HOLDS)["macd_pass"] is True
    assert _detail(monkeypatch, "Bullish", 4, hist=HIST_UP_4_AGO_HOLDS)["macd_pass"] is False


# ── Test 3: the state no longer holds on the last bar → never counts ───────────

@pytest.mark.parametrize("W", [1, 4, 5, 8, 10, 50])
def test_macd_cross_up_with_histogram_back_below_zero_never_counts(monkeypatch, W):
    assert _detail(monkeypatch, "Bullish", W, hist=HIST_UP_4_AGO_LOST)["macd_pass"] is False


# ── Test 4: a cross 9 bars ago is outside an 8-bar window ──────────────────────

def test_macd_cross_9_bars_ago_not_counted_with_window_8(monkeypatch):
    assert _detail(monkeypatch, "Bullish", 8, hist=HIST_UP_9_AGO_HOLDS)["macd_pass"] is False
    assert _detail(monkeypatch, "Bullish", 10, hist=HIST_UP_9_AGO_HOLDS)["macd_pass"] is True


# ── Test 5: the same shapes for RSI and stochastic, and the bearish mirror ─────

def test_rsi_floor_cross_window_shapes(monkeypatch):
    assert _detail(monkeypatch, "Bullish", 8, rsi=RSI_UP_4_AGO_HOLDS)["rsi_pass"] is True
    assert _detail(monkeypatch, "Bullish", 1, rsi=RSI_UP_4_AGO_HOLDS)["rsi_pass"] is False
    for W in (1, 5, 8, 50):
        assert _detail(monkeypatch, "Bullish", W, rsi=RSI_UP_4_AGO_LOST)["rsi_pass"] is False
    assert _detail(monkeypatch, "Bullish", 8, rsi=RSI_UP_9_AGO_HOLDS)["rsi_pass"] is False
    assert _detail(monkeypatch, "Bullish", 10, rsi=RSI_UP_9_AGO_HOLDS)["rsi_pass"] is True


def test_stoch_oversold_cross_window_shapes(monkeypatch):
    assert _detail(monkeypatch, "Bullish", 8, stoch=STOCH_UP_4_AGO_HOLDS)["stoch_pass"] is True
    assert _detail(monkeypatch, "Bullish", 1, stoch=STOCH_UP_4_AGO_HOLDS)["stoch_pass"] is False
    for W in (1, 5, 8, 50):
        assert _detail(monkeypatch, "Bullish", W, stoch=STOCH_UP_4_AGO_LOST)["stoch_pass"] is False
    assert _detail(monkeypatch, "Bullish", 8, stoch=STOCH_UP_9_AGO_HOLDS)["stoch_pass"] is False
    assert _detail(monkeypatch, "Bullish", 10, stoch=STOCH_UP_9_AGO_HOLDS)["stoch_pass"] is True


def test_bearish_mirror_cross_down_4_bars_ago_counts_within_window(monkeypatch):
    d8 = _detail(monkeypatch, "Bearish", 8, hist=HIST_DOWN_4_AGO_HOLDS,
                 rsi=RSI_DOWN_4_AGO_HOLDS, stoch=STOCH_DOWN_4_AGO_HOLDS)
    assert (d8["macd_pass"], d8["rsi_pass"], d8["stoch_pass"]) == (True, True, True)
    assert d8["momentum_count"] == 3
    d1 = _detail(monkeypatch, "Bearish", 1, hist=HIST_DOWN_4_AGO_HOLDS,
                 rsi=RSI_DOWN_4_AGO_HOLDS, stoch=STOCH_DOWN_4_AGO_HOLDS)
    assert (d1["macd_pass"], d1["rsi_pass"], d1["stoch_pass"]) == (False, False, False)


def test_bearish_state_lost_never_counts(monkeypatch):
    for W in (1, 5, 8, 50):
        d = _detail(monkeypatch, "Bearish", W, hist=HIST_DOWN_4_AGO_LOST,
                    rsi=RSI_DOWN_4_AGO_LOST, stoch=STOCH_DOWN_4_AGO_LOST)
        assert (d["macd_pass"], d["rsi_pass"], d["stoch_pass"]) == (False, False, False)


# ── detail carries the window; a cfg without the key behaves as W = 1 ──────────

def test_detail_reports_setup_window_bars(monkeypatch):
    assert _detail(monkeypatch, "Bullish", 8, hist=HIST_UP_4_AGO_HOLDS)["setup_window_bars"] == 8


def test_missing_setup_window_bars_defaults_to_one(monkeypatch):
    d = _detail(monkeypatch, "Bullish", None, hist=HIST_UP_4_AGO_HOLDS)
    assert d["macd_pass"] is False
    assert d["setup_window_bars"] == 1
